using System;using System.IO;using System.Linq;using System.Text;using UnityEngine;using UnityEditor;
[InitializeOnLoad]public static class CoastalScopeAudit{
static CoastalScopeAudit(){EditorApplication.update+=Poll;}static void Poll(){if(!File.Exists("CoastalScopeAudit.request")||EditorApplication.isCompiling)return;File.Delete("CoastalScopeAudit.request");var b=new StringBuilder();try{var c=SceneView.lastActiveSceneView.camera;b.AppendLine("CAMERA pos="+c.transform.position+" forward="+c.transform.forward+" ortho="+c.orthographic+" size="+c.orthographicSize+" pixels="+c.pixelWidth+"x"+c.pixelHeight+" aspect="+c.aspect);b.AppendLine("Garden viewport="+c.WorldToViewportPoint(new Vector3(220.98f,27.72f,127.2f)));var points=new[]{new Vector2(350,625),new Vector2(425,690),new Vector2(500,710),new Vector2(565,743),new Vector2(690,790),new Vector2(1030,816),new Vector2(1270,812),new Vector2(1375,780),new Vector2(1430,718),new Vector2(1430,585),new Vector2(1420,470),new Vector2(1410,377),new Vector2(1387,287)};var plane=new Plane(Vector3.up,new Vector3(0,27.7f,0));foreach(var p in points){var ray=c.ViewportPointToRay(new Vector3(p.x/1718,1-p.y/943,0));if(plane.Raycast(ray,out float d))b.AppendLine("MARK "+p+" world="+ray.GetPoint(d).ToString("F3"));}}catch(Exception e){b.AppendLine("FAILED "+e);}File.WriteAllText("FinalEnvironmentRoadReview/CoastalScopeAudit.txt",b.ToString());}}
